<h1>Pending Signups</h1><table><tr><th>Owner</th><th>Company</th><th>Mobile</th><th>Email</th><th>City/State</th><th>Scheme</th><th>Status</th><th>Actions</th></tr><?php foreach($pending as $p): ?><tr><td><?= htmlspecialchars($p['owner_name']) ?></td><td><?= htmlspecialchars($p['company_name']) ?></td><td><?= htmlspecialchars($p['mobile']) ?></td><td><?= htmlspecialchars($p['email']) ?></td><td><?= htmlspecialchars($p['city'].'/'.$p['state']) ?></td><td><?= htmlspecialchars($p['scheme_key']) ?></td><td><span class="badge"><?= htmlspecialchars($p['status'] ?? 'pending') ?></span></td><td><?php if(($p['status']??'')==='pending'): ?><form method="post" style="display:inline"><input type="hidden" name="signup_id" value="<?= htmlspecialchars($p['signup_id']) ?>"><button class="btn" name="action" value="verify">Verify</button></form> <form method="post" style="display:inline"><input type="hidden" name="signup_id" value="<?= htmlspecialchars($p['signup_id']) ?>"><button class="btn secondary" name="action" value="reject">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></table>
